const AGENT = 'https://auloava.netlify.app/.netlify/functions/agent';
const KEY = process.env.AGENT_KEY || 'auloava';
const res = await fetch(AGENT, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'x-agent-key': KEY },
  body: JSON.stringify({ action: 'list-products' })
});
const data = await res.json();
const products = data.products || [];
if (!products.length) throw new Error('Sin productos');
const pick = products[Math.floor(Math.random() * products.length)];
return [{ json: { product: pick } }];

const AGENT = 'https://auloava.netlify.app/.netlify/functions/agent';
const KEY = process.env.AGENT_KEY || 'auloava';
const product = $input.all()[0].json.product;
const res = await fetch(AGENT, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'x-agent-key': KEY },
  body: JSON.stringify({ action: 'generate-post', product, platform: 'facebook' })
});
const data = await res.json();
if (!data.ok) throw new Error(data.error || 'generate-post fallo');
return [{ json: { platform: 'facebook', product, draft: data.draft } }];

const TOKEN = process.env.FACEBOOK_PAGE_TOKEN;
const PAGE = process.env.FACEBOOK_PAGE_ID || '61593917245819';
const item = $input.all()[0].json;
const product = item.product;
const imgs = (product.images && product.images.length) ? product.images : [product.image];
const results = [];
for (const url of imgs) {
  const res = await fetch('https://graph.facebook.com/v18.0/' + PAGE + '/photos', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ url: url, caption: item.draft + '\n' + product.affiliateUrl, access_token: TOKEN })
  });
  results.push({ status: res.status });
}
return [{ json: { platform: 'facebook', count: results.length, results } }];
